// SPDX-License-Identifier: MIT
// Shadewatch Vigil (Prismheart campaign), plain C++17 for the Unreal binding. A port of
// tools/minigames/shadewatch.py (prism-shard-dev), which stays the rules authority. Seeding is CPython-compatible
// (DaedalusPyRandomCore.h, "shadewatch:<seed>:<difficulty>"), so the same seed spawns the same shades as the Python game.
// Byte parity goes through engines/unreal/core-test/shadewatch_parity.txt (shadewatch_core_test.cpp), generated by
// tools/minigames/shadewatch_parity.py.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

namespace daedalus { namespace shadewatch {

inline const char* GameId() { return "shadewatch"; }
inline const char* Title() { return "Shadewatch Vigil"; }

struct Difficulty { const char* Name; int Lanes; int Length; double Spawn; int Turns; int Hearts; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 2, 6, 0.45, 20, 3 }, { "normal", 3, 6, 0.33, 24, 3 }, { "hard", 4, 6, 0.28, 28, 3 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

constexpr int BoonDelta = 1;  // Spirit Boon (Lantern Newt): hearts +1 per level (hephaestus R2-9; level 2 = 5+ summons)
/** FindDifficulty with a Spirit Boon level 0..2 applied to Hearts (PrismGame boon, floor 0). Nullptr on a bad level. */
inline const Difficulty* FindDifficulty(const std::string& Name, int Boon)
{
	if (Boon == 0) return FindDifficulty(Name);
	if (Boon < 0 || Boon > 2) return nullptr;
	struct Boosted { Difficulty Table[2][DifficultyCount]; };
	static const Boosted B = [] {
		Boosted Out{};
		for (int L = 0; L < 2; ++L)
			for (int I = 0; I < DifficultyCount; ++I)
			{
				Out.Table[L][I] = Difficulties()[I];
				Out.Table[L][I].Hearts = std::max(0, Out.Table[L][I].Hearts + BoonDelta * (L + 1));
			}
		return Out;
	}();
	for (int I = 0; I < DifficultyCount; ++I)
	{
		if (Name == B.Table[Boon - 1][I].Name) return &B.Table[Boon - 1][I];
	}
	return nullptr;
}

constexpr int LightMax = 5, NovaCost = 3, NovaReach = 2;

enum class Kind : int { Flare = 0, Kindle, Nova };
struct Action { Kind K = Kind::Kindle; int Lane = 0; };

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<std::vector<int>> Lanes;  // shade positions per lane, ascending; 0 is next to the heart
	int Hearts = 0, Light = 0, TurnNo = 0, Burned = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, BadLane, NoLight, GameOver };

	/** PrismGame.start + Game.setup. False on an unknown difficulty. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName, int Boon = 0)
	{
		Diff = FindDifficulty(DifficultyName, Boon);
		if (!Diff) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		Lanes.assign(static_cast<size_t>(Diff->Lanes), {});
		Hearts = Diff->Hearts; Light = 1; TurnNo = 0; Burned = 0;
		Spawn();
		return true;
	}

	/** One random() per lane, always drawn first, as in Python's short-circuit order. */
	void Spawn()
	{
		const int Far = Diff->Length - 1;
		for (std::vector<int>& Lane : Lanes)
			if (Rng.RandomDouble() < Diff->Spawn && (Lane.empty() || Lane.back() < Far)) Lane.push_back(Far);
	}

	/** Game.act. Result text matches the Python return value. */
	Act Step(const Action& A, std::string& Result)
	{
		if (Over) return Act::GameOver;
		int Fire = 0;
		if (A.K == Kind::Flare)
		{
			if (A.Lane < 0 || A.Lane >= static_cast<int>(Lanes.size())) return Act::BadLane;
			std::vector<int>& Lane = Lanes[static_cast<size_t>(A.Lane)];
			if (!Lane.empty()) { Lane.erase(Lane.begin()); Fire = 1; }
		}
		else if (A.K == Kind::Kindle) Light = std::min(LightMax, Light + 1);
		else
		{
			if (Light < NovaCost) return Act::NoLight;
			Light -= NovaCost;
			for (std::vector<int>& Lane : Lanes)
			{
				const auto Keep = std::stable_partition(Lane.begin(), Lane.end(), [](int P) { return P > NovaReach; });
				Fire += static_cast<int>(Lane.end() - Keep);
				Lane.erase(Keep, Lane.end());
			}
		}
		Burned += Fire; Score += 5 * Fire;
		int Hits = 0;
		for (std::vector<int>& Lane : Lanes)
		{
			std::vector<int> Next;
			for (int P : Lane) { if (P - 1 < 0) ++Hits; else Next.push_back(P - 1); }
			std::sort(Next.begin(), Next.end());
			Lane = Next;
		}
		Hearts -= Hits; ++TurnNo;
		if (Hearts <= 0) { Over = true; Won = false; Result = "the heart dims"; return Act::Ok; }
		Score += 1;
		if (TurnNo >= Diff->Turns) { Score += 10 * Hearts; Over = Won = true; Result = "dawn: the vigil holds"; return Act::Ok; }
		Spawn();
		Result = "burned " + std::to_string(Fire) + (Hits ? ", " + std::to_string(Hits) + " shade(s) struck the heart" : "");
		return Act::Ok;
	}

	/** Game.demo_action: the scripted watcher. */
	Action DemoAction() const
	{
		struct Front { int P, I; };
		std::vector<Front> Fronts, Near;
		for (size_t I = 0; I < Lanes.size(); ++I) if (!Lanes[I].empty()) Fronts.push_back({ Lanes[I].front(), static_cast<int>(I) });
		for (const Front& F : Fronts) if (F.P == 0) Near.push_back(F);
		if (Near.size() >= 2 && Light >= NovaCost) return { Kind::Nova, 0 };
		if (!Near.empty()) return { Kind::Flare, Near.front().I };
		int Close = 0; for (const Front& F : Fronts) if (F.P <= NovaReach) ++Close;
		if (Close >= 2 && Light >= NovaCost) return { Kind::Nova, 0 };
		if (!Fronts.empty())
		{
			const Front Low = *std::min_element(Fronts.begin(), Fronts.end(), [](const Front& X, const Front& Y) { return X.P != Y.P ? X.P < Y.P : X.I < Y.I; });
			if (Low.P <= 1 || Light >= LightMax) return { Kind::Flare, Low.I };
		}
		return { Kind::Kindle, 0 };
	}

	std::string LanesString() const
	{
		std::string S;
		for (size_t I = 0; I < Lanes.size(); ++I)
		{
			if (I) S += "|";
			for (size_t J = 0; J < Lanes[I].size(); ++J) S += (J ? "," : "") + std::to_string(Lanes[I][J]);
		}
		return S;
	}
};

} } // namespace daedalus::shadewatch
